package hu.taliann.icesmp.classspec.integration;
import hu.taliann.icesmp.archer.ArcherGameplayService;import hu.taliann.icesmp.classspec.application.ClassSpecRuntimePort;import hu.taliann.icesmp.classspec.application.ProfileSessionRegistry;import hu.taliann.icesmp.evoker.EvokerGameplayService;import hu.taliann.icesmp.monk.MonkGameplayService;import hu.taliann.icesmp.shaman.ShamanGameplayService;import hu.taliann.icesmp.listeners.AbilityCatalystListener;import hu.taliann.icesmp.managers.*;import hu.taliann.icesmp.playerprofile.domain.section.ClassSpecSection;import hu.taliann.icesmp.session.PlayerStateCleanup;import hu.taliann.icesmp.spells.Spell;import hu.taliann.icesmp.warrior.WarriorGameplayService;import org.bukkit.Bukkit;import org.bukkit.entity.Player;import org.bukkit.plugin.java.JavaPlugin;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.AtomicBoolean;import java.util.function.*;
public final class BukkitClassSpecRuntimeAdapter implements ClassSpecRuntimePort{
private final JavaPlugin plugin;private final JobManager jobs;private final SpecializationManager specs;private final AbilityCatalystListener catalyst;private final SpellRegistry spells;private final ResourceManager resources;private final PetManager pets;private final List<PlayerStateCleanup> owners=new CopyOnWriteArrayList<>();private final ProfileSessionRegistry sessions;private final AtomicBoolean accepting=new AtomicBoolean(true),wired=new AtomicBoolean(false);private volatile Consumer<UUID> switchCleanup=i->{};private volatile Consumer<Player> post=p->{};
public BukkitClassSpecRuntimeAdapter(JavaPlugin p,JobManager j,SpecializationManager s,AbilityCatalystListener c,PetManager pet,ResourceManager r,SpellRegistry sp,ProfileSessionRegistry ss){plugin=Objects.requireNonNull(p);jobs=Objects.requireNonNull(j);specs=Objects.requireNonNull(s);catalyst=Objects.requireNonNull(c);pets=Objects.requireNonNull(pet);resources=Objects.requireNonNull(r);spells=Objects.requireNonNull(sp);sessions=Objects.requireNonNull(ss);owners.add(catalyst);owners.add(pets);owners.add(resources);}
public void registerTransientOwner(PlayerStateCleanup o){owners.add(Objects.requireNonNull(o));}public void setLoadoutSwitchCleanup(Consumer<UUID> c){switchCleanup=c==null?i->{}:c;}public void setPostReconcile(Consumer<Player> c){post=c==null?p->{}:c;}
private void wire(){if(wired.get())return;WarriorGameplayService w=specs.warriorGameplayService().orElse(null);EvokerGameplayService e=specs.evokerGameplayService().orElse(null);ArcherGameplayService a=specs.archerGameplayService().orElse(null);ShamanGameplayService sh=specs.shamanGameplayService().orElse(null);MonkGameplayService m=specs.monkGameplayService().orElse(null);if(w==null||e==null||a==null||sh==null||m==null||!wired.compareAndSet(false,true))return;catalyst.setWarriorGameplayService(w);catalyst.setEvokerGameplayService(e);catalyst.setArcherGameplayService(a);catalyst.setShamanGameplayService(sh);catalyst.setMonkGameplayService(m);resources.setHudSuffix(p->w.hudSuffix(p).append(e.hudSuffix(p)).append(a.hudSuffix(p)).append(sh.hudSuffix(p)).append(m.hudSuffix(p)));specs.setSwitchSafetyResource(resources);w.setCombatTracker(resources);e.setCombatTracker(resources);a.setCombatTracker(resources);sh.setCombatTracker(resources);m.setCombatTracker(resources);a.setPetManager(pets);pets.setPetDeathHook(a::onPetDeath);owners.add(w);owners.add(e);owners.add(a);owners.add(sh);owners.add(m);switchCleanup=id->{w.clearSpecializationState(id);e.clearSpecializationState(id);a.clearSpecializationState(id);sh.clearSpecializationState(id);m.clearSpecializationState(id);};post=p->{w.reconcileProfile(p);e.reconcileProfile(p);a.reconcileProfile(p);sh.reconcileProfile(p);m.reconcileProfile(p);catalyst.refreshSoulbond(p);};}
public CompletionStage<Void> profileCommitted(UUID id,UUID t,ClassSpecSection prev,ClassSpecSection d,MutationKind k){Objects.requireNonNull(prev);Objects.requireNonNull(d);wire();if(!ClassSpecRuntimePort.requiresRuntimeReconciliation(k))return current(id,t)?CompletableFuture.completedFuture(null):CompletableFuture.failedFuture(new ProfileSessionRegistry.StaleSessionException(id,t));if(k==MutationKind.SELECT&&Objects.equals(prev.activeSlot(),d.activeSlot())&&activeSpec(prev).equals(activeSpec(d)))return current(id,t)?CompletableFuture.completedFuture(null):CompletableFuture.failedFuture(new ProfileSessionRegistry.StaleSessionException(id,t));return reconcile(id,t,d,d.isGameplayUsable(),k);}public CompletionStage<Void> failClosed(UUID id,UUID t,String reason){wire();return reconcile(id,t,null,false,null);}
private CompletionStage<Void> reconcile(UUID id,UUID t,ClassSpecSection d,boolean regrant,MutationKind k){if(!accepting.get())return CompletableFuture.failedFuture(new IllegalStateException("Profile runtime adapter stopped"));if(!current(id,t))return CompletableFuture.failedFuture(new ProfileSessionRegistry.StaleSessionException(id,t));Player p=Bukkit.getPlayer(id);if(p==null){try{if(!current(id,t))throw new ProfileSessionRegistry.StaleSessionException(id,t);clear(id,k);return CompletableFuture.completedFuture(null);}catch(Throwable x){return CompletableFuture.failedFuture(x);}}Predicate<String> revoke=s->s.startsWith(JobManager.SOURCE_BASE_PREFIX)||s.startsWith(JobManager.SOURCE_SPEC_PREFIX);return jobs.revokeGrantsFromV2(p,revoke).thenCompose(v->owner(id,t,p,()->clear(id,k))).thenCompose(v->regrant?jobs.applyAutoUnlocksV2(p,d):CompletableFuture.completedFuture(null)).thenCompose(v->regrant?specs.applyClassSpecializationUnlocksV2(p,d):CompletableFuture.completedFuture(null)).thenCompose(v->owner(id,t,p,()->post.accept(p))).thenCompose(v->k==MutationKind.SELECT?owner(id,t,p,()->AdvancementService.award(p,"first_spec")):CompletableFuture.completedFuture(null));}
private CompletionStage<Void> owner(UUID id,UUID t,Player p,Runnable a){CompletableFuture<Void> f=new CompletableFuture<>();p.getScheduler().run(plugin,x->{if(!accepting.get()){f.completeExceptionally(new IllegalStateException("Profile runtime adapter stopped"));return;}if(!current(id,t)){f.completeExceptionally(new ProfileSessionRegistry.StaleSessionException(id,t));return;}try{a.run();f.complete(null);}catch(Throwable z){f.completeExceptionally(z);}},()->f.completeExceptionally(new IllegalStateException("Player scheduler rejected Profile v2 reconciliation")));return f;}private boolean current(UUID id,UUID t){return accepting.get()&&sessions.isCurrent(id,t);}private void clear(UUID id,MutationKind k){boolean sw=k==MutationKind.LOADOUT_SWITCH;for(PlayerStateCleanup o:owners){if(sw&&(o==resources||o==catalyst||o instanceof WarriorGameplayService||o instanceof EvokerGameplayService||o instanceof ArcherGameplayService||o instanceof ShamanGameplayService||o instanceof MonkGameplayService))continue;o.clearPlayerState(id);}if(sw)switchCleanup.accept(id);for(Spell s:spells.getAll())s.clearPlayerState(id);}private static String activeSpec(ClassSpecSection p){return p.activeSlot()==null?"":p.loadout(p.activeSlot()).specializationId();}public void stop(){accepting.set(false);}}
